input.oldString:
// background
    ctx.fillStyle = '#001';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    // ship
    ctx.fillStyle = '#0f0';
    ctx.fillRect(ship.x, ship.y, ship.w, ship.h);
    // obstacles
    ctx.fillStyle = '#f44';
    obstacles.forEach(o => ctx.fillRect(o.x, o.y, o.w, o.h));
    // orbs
    ctx.fillStyle = '#ff0';
    orbs.forEach(o => ctx.fillRect(o.x, o.y, o.w, o.h));

input.newString:
// background gradient (nebula)
    const bgGrad = ctx.createLinearGradient(0, 0, 0, canvas.height);
    bgGrad.addColorStop(0, '#001');
    bgGrad.addColorStop(1, '#003');
    ctx.fillStyle = bgGrad;
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    // stars
    ctx.fillStyle = '#fff';
    stars.forEach(s => {
      ctx.globalAlpha = s.alpha;
      ctx.fillRect(s.x, s.y, 1, 1);
    });
    ctx.globalAlpha = 1;
    // ship (triangle)
    ctx.fillStyle = '#0f0';
    ctx.beginPath();
    ctx.moveTo(ship.x, ship.y + ship.h / 2);
    ctx.lineTo(ship.x + ship.w, ship.y);
    ctx.lineTo(ship.x + ship.w, ship.y + ship.h);
    ctx.closePath();
    ctx.fill();
    // obstacles (asteroid circles with gradient)
    obstacles.forEach(o => {
      const grad = ctx.createRadialGradient(o.x + o.w / 2, o.y + o.h / 2, o.w / 4, o.x + o.w / 2, o.y + o.h / 2, o.w / 2);
      grad.addColorStop(0, '#f44');
      grad.addColorStop(1, '#600');
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.arc(o.x + o.w / 2, o.y + o.h / 2, o.w / 2, 0, Math.PI * 2);
      ctx.fill();
    });
    // orbs (glowing energy)
    ctx.fillStyle = '#ff0';
    ctx.shadowColor = '#ff0';
    ctx.shadowBlur = 15;
    orbs.forEach(o => {
      ctx.beginPath();
      ctx.arc(o.x + o.w / 2, o.y + o.h / 2, o.w / 2, 0, Math.PI * 2);
      ctx.fill();
    });
    ctx.shadowBlur = 0;

